@startuml

class Department {}

class Room {}

class Bed {}

class Category {
  + price: double
}

class RestHome extends Category {}

class RestAndNursingHome extends Category {}

class ServiceFlat extends Category {}

class Inhabitant {
  + identificationData: string
}

class Registration {
  + registrationDate: date
}

class Assessment {
  + assessmentDate: date
  + needs: string
}

class WaitingListPosition {
  + position: int
}

class Proposal {
  + proposalDate: date
  + status: string
}

class Stay {
  + startDate: date
  + endDate: date
  + isSuspended: boolean
  + isInvalidated: boolean
  + status: string
}

class Invoice {
  + billingDate: date
  + outstandingAmount: double
  + status: string
}

class Payment {
  + amount: double
  + paymentDate: date
}

class CreditNote {
  + amount: double
  + issueDate: date
}

Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "*" -- "1" Category
Inhabitant "1" -- "*" Stay
Stay "*" -- "1" Category
Inhabitant "1" -- "*" Registration
Registration "1" -- "0..1" Assessment
Assessment "1" -- "1" WaitingListPosition
WaitingListPosition "*" -- "1" Category
WaitingListPosition "0..1" -- "0..1" Proposal
Proposal "1" -- "1" Inhabitant
Stay "1" -- "*" Invoice
Invoice "1" -- "*" Payment
Invoice "1" -- "0..1" CreditNote
Inhabitant "1" -- "*" Invoice

@enduml

